import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BbQUUm7J.js";const p=JSON.parse('{"title":"Security Model","description":"","frontmatter":{},"headers":[],"relativePath":"reference/security.md","filePath":"reference/security.md","lastUpdated":1794934948000}'),i={name:"reference/security.md"};function n(s,e,d,l,c,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="security-model" tabindex="-1">Security Model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security Model&quot;">​</a></h1><p>The CLI&#39;s security posture rests on one architectural decision — <strong>identity and custody are decoupled</strong> — plus fail-closed defaults everywhere money could move.</p><h2 id="dual-plane-architecture" tabindex="-1">Dual-plane architecture <a class="header-anchor" href="#dual-plane-architecture" aria-label="Permalink to &quot;Dual-plane architecture&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plane</th><th>Holds</th><th>Can do</th><th>Cannot do</th></tr></thead><tbody><tr><td><strong>Identity</strong> (web session, <code>furlpay login</code>)</td><td>Read-only session cookie (<code>account:read</code>)</td><td>Read balances, KYC tier, order blotter</td><td>Move funds — it holds no signing keys</td></tr><tr><td><strong>Execution</strong> (local signing)</td><td>Keys in Ledger / extension / keystore / agent wallets</td><td>Sign orders &amp; transfers locally</td><td>Leave the machine — zero key material is transmitted</td></tr></tbody></table><h2 id="custody-options" tabindex="-1">Custody options <a class="header-anchor" href="#custody-options" aria-label="Permalink to &quot;Custody options&quot;">​</a></h2><ol><li><strong>Hardware</strong> — Ledger Nano S/X/Stax over USB HID, clear-signed on the device screen</li><li><strong>Extension loopback</strong> — Freighter / Albedo bridge on <code>127.0.0.1:4024</code></li><li><strong>Encrypted keystore</strong> — PBKDF2 (100k, SHA-512) + AES-256-GCM at <code>~/.furlpay/keystore.enc</code></li><li><strong>Delegated agent wallets</strong> — EIP-712 Phantom Agent keys (Chain ID 1337) with file-locked spend policies</li><li><strong>Exchange API</strong> — Binance HMAC keys, withdrawal capability structurally absent</li></ol><h2 id="threat-model-defenses" tabindex="-1">Threat model &amp; defenses <a class="header-anchor" href="#threat-model-defenses" aria-label="Permalink to &quot;Threat model &amp; defenses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Threat</th><th>Defense</th></tr></thead><tbody><tr><td>Stolen web session cookie</td><td>Scope decoupling — cookie is read-only; no signing keys exist server-side</td></tr><tr><td>Info-stealer malware</td><td>OS-bound sealing (DPAPI / <code>0600</code> POSIX); secrets never in plaintext, never in argv, echo suppressed on interactive input</td></tr><tr><td>Key in shell history</td><td>Argv rejection — secrets via stdin or environment only</td></tr><tr><td>AI prompt injection (&quot;trade $100k&quot;)</td><td>Read-only MCP default — value-moving tools are structurally absent from tools/list and refused with <code>EXECUTION_MODE_REQUIRED</code>; execution mode adds two-phase preview→confirm (hash-bound, single-use, policy re-run on the STORED amount); OS-file-locked caps (single-tx + daily) evaluated atomically; <code>requiresUserInteraction</code> forces human <code>[y/N]</code></td></tr><tr><td>Compromised exchange API key</td><td>Structural absence of withdrawal methods + your Binance-side withdrawal disable + IP binding</td></tr><tr><td>Adverse slippage / MEV</td><td>Pre-trade guardrails; orders &gt;15% from mid rejected as fat-finger; per-side slippage caps with absolute-deviation math; 50 bps default market buffer</td></tr><tr><td>Credential exfiltration via <code>--api-base</code></td><td>Cookie only attaches to <code>furlpay.com</code> over TLS or loopback; other targets go credential-less, loudly</td></tr><tr><td>Payment replay</td><td>Persistent nonce ledger + stable idempotency keys; unknown outcomes are never retried under a new key</td></tr><tr><td>Escrow proof forgery</td><td>ECDSA seller-signature verification, spec-hash equality, ledger-clock timestamps</td></tr><tr><td>Backdated auto-release</td><td><code>submittedAt</code> from caller input is discarded — ledger clock only</td></tr><tr><td>Compromised or diverging price source</td><td>Oracle aggregator gates on cross-source agreement (±1–3% per asset): a disagreement returns per-source readings with a <strong>null price</strong> — never a blended number; sanity bands drop out-of-band prints; the Pyth provider is inactive unless an operator configures a gateway + verified feed IDs, and rejects stale publishes</td></tr></tbody></table><h2 id="money-math-integrity" tabindex="-1">Money-math integrity <a class="header-anchor" href="#money-math-integrity" aria-label="Permalink to &quot;Money-math integrity&quot;">​</a></h2><ul><li><strong>BigInt integer cents</strong> for payment amounts; fixed-point decimals for PnL/funding — sign handling correct for fractional negatives (<code>-0.50</code> stays negative)</li><li>Audited <strong>$10M single-transfer ceiling</strong> and per-command bounds</li><li>Slippage = absolute deviation from best executable price — sell-side dumps cannot bypass the cap</li><li>No <code>Math.random()</code> anywhere security-relevant; <code>crypto.randomUUID()</code> / <code>crypto.getRandomValues()</code> only</li></ul><h2 id="distribution-security" tabindex="-1">Distribution security <a class="header-anchor" href="#distribution-security" aria-label="Permalink to &quot;Distribution security&quot;">​</a></h2><ul><li>npm installs integrity-checked by the registry (sha512 + signatures); the package publishes with npm provenance (sigstore, OIDC-bound to the repo and workflow)</li><li>Release assets (tarball, <code>checksums.txt</code>, CycloneDX SBOM) carry build-provenance attestations — <code>gh attestation verify --repo FurlPay/furlpay-cli &lt;file&gt;</code></li><li>Release builds gated on tag/version consistency, full typecheck + tests, and a three-OS smoke install of the packed tarball before publishing</li><li>No postinstall scripts; no secrets in the package; CI actions are SHA-pinned</li></ul><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>See <a href="https://github.com/FurlPay/furlpay-cli/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a> in the repository for responsible-disclosure details.</p>',14)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
